ValidationRule.errorConditionFormula:
OR(
        AND(
        TEXT(Lost_Reason_new__c) = "Feature gap",
        PICKLISTCOUNT(Feature_Gap__c) = 0
        ),
        AND(
        TEXT(Lost_Reason_new__c) = "Service gap (example: Visas, Benefits, Time to Hire etc)",
        PICKLISTCOUNT(Service_Gap__c) = 0
        )
        )
